import { describe, expect, it, vi } from "vitest";
vi.mock("@/lib/db", () => ({ db: {} }));
import {
  getClientEntitlements,
  type EntitlementUser,
} from "@/lib/entitlements";
import { planTutorials } from "@/components/tutorial-content";

const now = new Date("2026-10-28T00:00:00Z");
function access(premium: boolean, gated: boolean) {
  const user: EntitlementUser = {
    id: "tutorial-owner",
    plan: "FREE",
    subscriptionStatus: "NONE",
    currentPeriodStart: null,
    currentPeriodEnd: null,
    dodoSubscriptionId: null,
    gracePeriodEnd: null,
    planOverride: premium ? "PAID" : "FREE",
    planOverrideStartsAt: new Date("2026-10-01T00:00:00Z"),
    planOverrideExpiresAt: null,
    grandfatheredUntil: null,
    isSuspended: false,
    deletionRequestedAt: null,
    gmailAuthorized: true,
  };
  return getClientEntitlements(
    user,
    { sendingEnabled: true, paidGatingEnabled: gated },
    now,
  );
}
for (const premium of [false, true]) {
  for (const gated of [false, true]) {
    describe(`tutorials: Premium=${premium}, quota gating=${gated}`, () => {
      const entitlement = access(premium, gated);
      const step = (path: string, hint: string) =>
        planTutorials(path, entitlement)!.find((step) => step.hint === hint)!
          .text;
      it("has the complete workspace guide on each route", () => {
        expect(
          Object.fromEntries(
            [
              "compose",
              "templates",
              "contacts",
              "usage",
              "history",
              "settings",
            ].map((route) => [
              route,
              planTutorials(`/${route}`, entitlement)!.map(({ hint }) => hint),
            ]),
          ),
        ).toEqual({
          compose: [
            "search",
            "template",
            "roles",
            "shortlist",
            "resume",
            "queue",
          ],
          templates: ["placeholders", "editor", "preview", "saved"],
          contacts: ["contacts", "contact-form", "import", "import-review"],
          usage: ["limits", "subscription", "queue", "uncertain"],
          history: [
            "totals",
            "queue",
            "statuses",
            "replies",
            "history-shortlist",
          ],
          settings: [
            "preferences",
            "subscription",
            "gmail",
            "pdf",
            "reminders",
            "data",
          ],
        });
      });
      it("explains recipient review, manual approval, and individual sends", () => {
        expect(step("/compose", "shortlist")).toContain(
          `up to ${entitlement.limits.campaignRecipients}`,
        );
        expect(step("/compose", "shortlist")).toContain("yellow recipient");
        expect(step("/compose", "shortlist")).toContain(
          "pending deliveries stay disabled",
        );
        expect(step("/compose", "resume")).toContain(
          "mentioning a PDF in the message does not attach it",
        );
        expect(step("/compose", "queue")).toContain("Send to recipients");
        expect(step("/compose", "queue")).toContain("individual email");
        expect(step("/compose", "queue")).toContain("not confirmed delivery");
        expect(step("/usage", "queue")).toContain(
          "approve the batch in Compose",
        );
      });
      it("explains template, contact, and history workflows", () => {
        expect(step("/templates", "placeholders")).toContain("{{role}}");
        expect(step("/templates", "preview")).toContain("preview");
        expect(step("/templates", "saved")).toContain("Compose");
        expect(step("/contacts", "contact-form")).toContain("email");
        expect(step("/contacts", "import-review")).toContain(
          "duplicates are skipped",
        );
        expect(step("/history", "statuses")).toContain("filter buttons");
        expect(step("/history", "statuses")).toContain("Needs review");
        expect(step("/history", "replies")).toContain(
          "check Gmail Sent yourself",
        );
        expect(step("/history", "history-shortlist")).toContain(
          "Compose before sending",
        );
      });
      it("explains settings and allowance caveats", () => {
        expect(step("/settings", "gmail")).toContain("Reconnect Gmail");
        expect(step("/settings", "pdf")).toContain("Attach PDF");
        expect(step("/settings", "reminders")).toContain("never send");
        expect(step("/settings", "data")).toContain("cannot be undone");
        expect(step("/usage", "uncertain")).toContain(
          "never automatically resent",
        );
        expect(step("/usage", "limits")).toContain(
          gated ? "monthly emails" : "rolling 24 hours",
        );
      });
      it("explains preview customization and preference retention on both surfaces", () => {
        for (const [path, hint] of [
          ["/compose", "resume"],
          ["/templates", "preview"],
        ]) {
          expect(step(path, hint)).toContain(
            "Free includes Cyan preview highlights; Premium includes 10 colors.",
          );
          expect(step(path, hint)).toContain(
            premium ? "Use the color picker" : "Use the crown",
          );
          expect(step(path, hint)).toContain(
            premium ? "browser remembers" : "saved Premium color is kept",
          );
        }
      });
      it("describes themes, priority support and preview colors in plan help", () => {
        for (const path of ["/usage", "/settings"]) {
          expect(step(path, "subscription")).toContain(
            premium ? "all four themes" : "Chalk and Obsidian require Premium",
          );
          expect(step(path, "subscription")).toContain(
            premium
              ? "Your plan includes prioritized email support"
              : "Ordinary support remains available",
          );
          expect(step(path, "subscription")).toContain(
            "Premium includes 10 colors",
          );
        }
      });
      it("uses the current role and shortcut allowances", () => {
        expect(step("/settings", "preferences")).toContain(
          `Save up to ${premium ? 8 : 2} role shortcuts`,
        );
        expect(step("/settings", "preferences")).toContain(
          `Any contact job role · up to ${premium ? 8 : 2} saved shortcuts`,
        );
      });
      it("keeps rollout-dependent capabilities separate from plan customization", () => {
        const limited = gated && !premium;
        expect(
          step("/contacts", "import").includes("imports require Premium"),
        ).toBe(limited);
        expect(
          step("/history", "replies").includes("Undo require Premium"),
        ).toBe(limited);
        expect(
          step("/settings", "reminders").includes("reminders require Premium"),
        ).toBe(limited);
        expect(step("/usage", "limits")).toContain(
          gated ? "monthly emails" : "rolling 24 hours",
        );
      });
    });
  }
}
